<style>:root{font-family:Inter,Arial,sans-serif;--navy:#06275c;--dark:#071f4d;--red:#e20b24;--muted:#536684;--border:#cfd9e7}*{box-sizing:border-box}body{margin:0;color:var(--dark);background:#fff}.page{min-height:100vh;display:grid;grid-template-columns:1fr 1fr;background:linear-gradient(135deg,#fff,#f5f8fc)}.brand{position:relative;overflow:hidden;padding:58px 6vw 105px;display:flex;flex-direction:column;justify-content:flex-start;background:linear-gradient(145deg,#fff 55%,#edf4fb)}.brand:after{content:"";position:absolute;inset:auto -12% 0 -5%;height:38%;background:linear-gradient(160deg,transparent 0 15%,#dceafa 16% 18%,transparent 19% 24%,#e9f2fb 25%);opacity:.8}.logo{width:min(430px,75%);height:180px;object-fit:contain;object-position:left center;position:relative;z-index:2}.brand h1{font-size:40px;line-height:1.16;margin:34px 0 22px;max-width:620px;position:relative;z-index:2}.brand p{font-size:17px;line-height:1.75;color:var(--muted);max-width:520px;position:relative;z-index:2}.actions{display:flex;gap:14px;margin-top:25px;position:relative;z-index:2}.actions a{padding:13px 28px;border-radius:7px;text-decoration:none;font-weight:700}.primary{background:var(--red);color:white}.secondary{border:1px solid var(--navy);color:var(--navy);background:#fff}.building{position:absolute;left:0;right:0;bottom:0;height:30%;background:linear-gradient(120deg,#e7eef7,#c7d8eb);clip-path:polygon(0 52%,62% 0,100% 30%,100% 100%,0 100%);opacity:.85}.formwrap{padding:54px 5vw 105px;display:flex;align-items:center;justify-content:center}.card{width:min(640px,100%);background:rgba(255,255,255,.96);border:1px solid #edf0f5;border-radius:18px;padding:38px 48px;box-shadow:0 18px 48px rgba(10,39,91,.08);position:relative}.lang{position:absolute;right:28px;top:24px;color:var(--navy);font-weight:650}.cardlogo{display:block;width:300px;height:145px;object-fit:contain;margin:0 auto 8px}.accent{width:82px;height:5px;border-radius:9px;background:var(--red);margin:0 auto 20px}.card h2{text-align:center;font-size:35px;margin:0}.lead{text-align:center;color:var(--muted);font-size:16px;margin:8px 0 30px}.field{display:grid;gap:9px;font-weight:700;margin-bottom:20px}.field input{padding:15px 16px;border:1px solid var(--border);border-radius:8px;font:inherit;outline:none}.field input:focus{border-color:var(--navy);box-shadow:0 0 0 3px rgba(6,39,92,.08)}.row{display:flex;justify-content:space-between;align-items:center;margin:4px 0 25px;color:var(--muted)}.remember{display:flex;gap:9px;align-items:center}.forgot{color:var(--red);font-size:14px}.signin{width:100%;border:0;border-radius:7px;background:var(--red);color:white;font-size:17px;font-weight:800;padding:15px;cursor:pointer}.secure{text-align:center;border:1px solid var(--border);border-radius:7px;padding:14px;margin-top:26px;font-weight:700}.err{background:#fff0f1;border:1px solid #f5c7cc;color:#a21828;padding:12px;border-radius:8px;margin-bottom:18px}.footer{position:fixed;left:0;right:0;bottom:0;height:74px;background:var(--navy);color:#fff;display:flex;align-items:center;justify-content:space-around;gap:20px;padding:0 30px;font-size:12px;z-index:5}.footer strong{display:block;font-size:13px}.footer .footlogo{width:150px;height:58px;object-fit:contain;filter:brightness(0) invert(1)}@media(max-width:900px){.page{grid-template-columns:1fr}.brand{display:none}.formwrap{min-height:calc(100vh - 70px);padding:28px 16px 95px}.card{padding:32px 22px}.cardlogo{width:230px;height:125px}.card h2{font-size:30px}.footer{height:68px;overflow:auto;justify-content:flex-start}.footer>div:nth-child(n+4){display:none}}@media(max-width:480px){.lang{font-size:12px;right:18px}.card{padding-top:46px}.row{font-size:13px}.footer{padding:0 18px}}</style></head>
